namespace NotificationsApp.Services;

public record Notification(int Id, string Message, DateTime Timestamp);

public class NotificationService
{
    private int _nextId = 1;
    private readonly List<Notification> _notifications = new();
    private readonly Lock _lock = new();

    public NotificationService()
    {
        // Seed with initial fake data
        _notifications.AddRange(new[]
        {
            CreateNotification("Welcome to the app!"),
            CreateNotification("Your profile was updated."),
            CreateNotification("New feature: dark mode is available."),
        });
    }

    /// <summary>Returns all notifications available right now.</summary>
    public List<Notification> GetAll()
    {
        lock (_lock)
        {
            return _notifications.ToList();
        }
    }

    /// <summary>Returns only notifications newer than the given timestamp.</summary>
    public List<Notification> GetSince(DateTime since)
    {
        lock (_lock)
        {
            return _notifications.Where(n => n.Timestamp > since).ToList();
        }
    }

    /// <summary>Simulates an external system pushing a new notification.</summary>
    public void AddRandom()
    {
        string[] templates =
        [
            "Server deployment completed.",
            "You have a new follower.",
            "Disk usage alert: 85% full.",
            "Scheduled backup finished.",
            "New comment on your post.",
            "Security scan passed.",
        ];

        var msg = templates[Random.Shared.Next(templates.Length)];

        lock (_lock)
        {
            _notifications.Add(CreateNotification(msg));
        }
    }

    private Notification CreateNotification(string message)
        => new(Interlocked.Increment(ref _nextId), message, DateTime.UtcNow);
}

@page "/notifications"
@rendermode InteractiveServer
@implements IDisposable
@inject NotificationService Svc

<PageTitle>Notifications</PageTitle>

<h2>
    Notifications
    <span class="badge bg-primary rounded-pill ms-2">@_notifications.Count</span>
</h2>

@if (_notifications.Count == 0)
{
    <p><em>No notifications yet.</em></p>
}
else
{
    <ul class="list-group mt-3">
        @foreach (var n in _notifications.OrderByDescending(x => x.Timestamp))
        {
            <li class="list-group-item d-flex justify-content-between align-items-start">
                <span>@n.Message</span>
                <small class="text-muted">@n.Timestamp.ToString("HH:mm:ss")</small>
            </li>
        }
    </ul>
}

@code {
    private List<Notification> _notifications = new();
    private CancellationTokenSource? _cts;
    private DateTime _lastCheck;

    // Runs during both prerender AND interactive init.
    // On prerender it seeds the HTML; on interactive init it is called again,
    // but we only start polling once the component is truly interactive.
    protected override void OnInitialized()
    {
        _notifications = Svc.GetAll();
        _lastCheck = _notifications.Count > 0
            ? _notifications.Max(n => n.Timestamp)
            : DateTime.UtcNow;
    }

    // Called only once after the component is interactive in the browser —
    // never during static SSR prerender.
    protected override Task OnAfterRenderAsync(bool firstRender)
    {
        if (firstRender)
        {
            _cts = new CancellationTokenSource();
            _ = PollAsync(_cts.Token);
        }

        return Task.CompletedTask;
    }

    private async Task PollAsync(CancellationToken ct)
    {
        // Simulate the external system producing notifications over time.
        // In a real app, only GetSince would be called here.
        while (!ct.IsCancellationRequested)
        {
            try
            {
                await Task.Delay(TimeSpan.FromSeconds(5), ct);
            }
            catch (OperationCanceledException)
            {
                return;
            }

            Svc.AddRandom();

            var newer = Svc.GetSince(_lastCheck);
            if (newer.Count > 0)
            {
                _notifications.AddRange(newer);
                _lastCheck = newer.Max(n => n.Timestamp);
                await InvokeAsync(StateHasChanged);
            }
        }
    }

    public void Dispose()
    {
        _cts?.Cancel();
        _cts?.Dispose();
    }
}

